const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, terminal: false });

let inputLines = [];
rl.on('line', (line) => {
    inputLines.push(line);
});

rl.on('close', () => {
    let tokens = [];
    let lineIndex = 0;

    function nextToken() {
        while (tokens.length === 0) {
            if (lineIndex >= inputLines.length) return null;
            tokens = inputLines[lineIndex].trim().split(/\s+/).filter(x => x.length > 0);
            lineIndex++;
        }
        return tokens.shift();
    }

    function nextInt() {
        return parseInt(nextToken(), 10);
    }

    const n = nextInt();
    const k = nextInt();
    let min = Number.MAX_SAFE_INTEGER;

    for (let i = 1; i < k; i++) {
        if (n % i === 0) {
            const x = Math.floor(n / (i % k)) * k + i;
            if (x < min) min = x;
        }
    }

    console.log(min);
});
